'use client'

import Image from 'next/image'
import Link from 'next/link'
import { useId, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react'
import { CalendarDays, ChevronLeft, ChevronRight, Search } from 'lucide-react'

import { Breadcrumbs, type BreadcrumbItem } from '@/components/library/navigation/Breadcrumbs'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'

export type BlogListingPost = {
  slug: string
  title: string
  excerpt: string
  image: { src: string; alt: string }
  date: string
  dateTime?: string
  category?: string
  href: string
}

export type BlogListingLabels = {
  searchTitle?: string
  searchPlaceholder?: string
  searchButton?: string
  recentTitle?: string
  categoriesTitle?: string
  allLabel?: string
  readMore?: string
  previous?: string
  next?: string
  emptyMessage?: string
}

export type BlogFeaturedListingProps = {
  posts: BlogListingPost[]
  hero?: {
    title: string
    description?: string
    image: { src: string; alt: string }
    icon?: ReactNode
    breadcrumbs?: readonly BreadcrumbItem[]
  }
  perPage?: number
  featured?: boolean
  recent?: BlogListingPost[]
  categories?: Array<{ label: string; href: string }>
  labels?: BlogListingLabels
  className?: string
}

const normalize = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()

function PostDate({ post, className }: { post: BlogListingPost; className?: string }) {
  return (
    <time
      dateTime={post.dateTime}
      className={cn('inline-flex items-center gap-1.5 text-xs font-medium', className)}
    >
      <CalendarDays className="h-3.5 w-3.5" aria-hidden="true" />
      {post.date}
    </time>
  )
}

function ReadMore({ label }: { label: string }) {
  return (
    <span className="inline-flex items-center gap-1 text-xs font-bold uppercase tracking-wider text-primary">
      {label}
      <ChevronRight
        className="h-3.5 w-3.5 transition-transform group-hover:translate-x-0.5"
        aria-hidden="true"
      />
    </span>
  )
}

function FeaturedPost({ post }: { post: BlogListingPost }) {
  return (
    <Link
      href={post.href}
      className="group relative flex aspect-[4/5] items-end overflow-hidden rounded-2xl bg-muted shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring sm:aspect-[16/9]"
    >
      <Image
        src={post.image.src}
        alt={post.image.alt}
        fill
        priority
        className="object-cover transition duration-700 group-hover:scale-105"
        sizes="(min-width: 1024px) 66vw, 100vw"
      />
      <span className="absolute inset-0 bg-gradient-to-t from-black/85 via-black/30 to-transparent" />
      <span className="relative p-6 text-white md:p-8">
        {post.category ? (
          <span className="mb-3 inline-block rounded-full bg-primary px-3 py-1 text-xs font-semibold text-primary-foreground">
            {post.category}
          </span>
        ) : null}
        <PostDate post={post} className="flex text-white/80" />
        <span className="mt-2 block text-2xl font-bold leading-tight md:text-3xl">
          {post.title}
        </span>
      </span>
    </Link>
  )
}

function PostCard({ post, readMore }: { post: BlogListingPost; readMore: string }) {
  return (
    <Link
      href={post.href}
      className="group flex h-full flex-col overflow-hidden rounded-2xl border bg-card shadow-sm transition duration-300 hover:-translate-y-1 hover:border-primary/30 hover:shadow-xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      <span className="relative aspect-[16/10] overflow-hidden bg-muted">
        <Image
          src={post.image.src}
          alt={post.image.alt}
          fill
          className="object-cover transition duration-700 group-hover:scale-105"
          sizes="(min-width: 1280px) 22vw, (min-width: 640px) 45vw, 100vw"
        />
      </span>
      <span className="flex flex-1 flex-col p-5">
        <PostDate post={post} className="text-muted-foreground" />
        <span className="mt-3 block text-lg font-bold leading-snug group-hover:text-primary">
          {post.title}
        </span>
        <span className="mt-2 line-clamp-3 text-sm leading-6 text-muted-foreground">
          {post.excerpt}
        </span>
        <span className="mt-auto pt-5">
          <ReadMore label={readMore} />
        </span>
      </span>
    </Link>
  )
}

export function BlogFeaturedListing({
  posts,
  hero,
  perPage = 6,
  featured = true,
  recent = posts.slice(0, 4),
  categories,
  labels = {},
  className,
}: BlogFeaturedListingProps) {
  const {
    searchTitle = 'Pesquisar',
    searchPlaceholder = 'Pesquisar...',
    searchButton = 'Buscar',
    recentTitle = 'Posts recentes',
    categoriesTitle = 'Categorias',
    allLabel = 'Todas',
    readMore = 'Ler mais',
    previous = 'Anterior',
    next = 'Próxima',
    emptyMessage = 'Nenhum artigo encontrado.',
  } = labels
  const id = useId()
  const listRef = useRef<HTMLDivElement>(null)
  const [draft, setDraft] = useState('')
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState<string | null>(null)
  const [page, setPage] = useState(1)

  const derivedCategories = useMemo(
    () => Array.from(new Set(posts.flatMap((post) => (post.category ? [post.category] : [])))),
    [posts],
  )

  const term = normalize(query.trim())
  const filtered = posts.filter(
    (post) =>
      (!category || post.category === category) &&
      (!term || normalize([post.title, post.excerpt, post.category].join(' ')).includes(term)),
  )
  const filtering = Boolean(term || category)
  const highlight = featured && !filtering ? filtered[0] : undefined
  const rest = highlight ? filtered.slice(1) : filtered
  const pageCount = Math.max(1, Math.ceil(rest.length / perPage))
  const currentPage = Math.min(page, pageCount)
  const visible = rest.slice((currentPage - 1) * perPage, currentPage * perPage)

  const goTo = (target: number) => {
    setPage(target)
    listRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }

  const submitSearch = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    setQuery(draft)
    setPage(1)
  }

  const selectCategory = (value: string | null) => {
    setCategory(value)
    setPage(1)
  }

  return (
    <>
      {hero ? (
        <header className="relative isolate overflow-hidden bg-foreground text-white">
          <Image
            src={hero.image.src}
            alt={hero.image.alt}
            fill
            priority
            className="-z-20 object-cover"
            sizes="100vw"
          />
          <span className="absolute inset-0 -z-10 bg-gradient-to-b from-black/80 via-black/70 to-primary/60" />
          <div className="container flex min-h-64 flex-col pb-6 pt-14 md:min-h-80 md:pt-20">
            <div className="mx-auto max-w-2xl flex-1 text-center">
              {hero.icon ? (
                <span className="mb-3 inline-flex text-primary-foreground/90 [&_svg]:h-7 [&_svg]:w-7">
                  {hero.icon}
                </span>
              ) : null}
              <h1 className="text-4xl font-bold tracking-tight md:text-5xl">{hero.title}</h1>
              {hero.description ? (
                <p className="mt-4 text-base leading-7 text-white/80 md:text-lg">
                  {hero.description}
                </p>
              ) : null}
            </div>
            {hero.breadcrumbs?.length ? (
              <Breadcrumbs tone="inverted" items={hero.breadcrumbs} className="mt-10" />
            ) : null}
          </div>
        </header>
      ) : null}
      <section className={cn('py-16 md:py-20', className)} aria-label="Artigos do blog">
        <div className="container grid gap-12 lg:grid-cols-[minmax(0,1fr)_300px] lg:gap-0">
          <div ref={listRef} className="min-w-0 scroll-mt-28 lg:pr-10">
            <p className="sr-only" aria-live="polite">
              {filtered.length}{' '}
              {filtered.length === 1 ? 'artigo encontrado' : 'artigos encontrados'}
            </p>

            {highlight && currentPage === 1 ? (
              <div className="mb-8">
                <FeaturedPost post={highlight} />
              </div>
            ) : null}

            {visible.length ? (
              <ul className="grid gap-6 sm:grid-cols-2 xl:grid-cols-3">
                {visible.map((post) => (
                  <li key={post.slug}>
                    <PostCard post={post} readMore={readMore} />
                  </li>
                ))}
              </ul>
            ) : !highlight ? (
              <p className="rounded-2xl border border-dashed p-10 text-center text-muted-foreground">
                {emptyMessage}
              </p>
            ) : null}

            {pageCount > 1 ? (
              <nav
                className="mt-10 flex flex-wrap items-center justify-center gap-2"
                aria-label="Paginação do blog"
              >
                <button
                  type="button"
                  onClick={() => goTo(currentPage - 1)}
                  disabled={currentPage === 1}
                  className="inline-flex h-9 items-center gap-1 rounded-lg px-3 text-sm text-muted-foreground transition hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-40"
                >
                  <ChevronLeft className="h-4 w-4" aria-hidden="true" />
                  {previous}
                </button>
                {Array.from({ length: pageCount }, (_, index) => index + 1).map((number) => (
                  <button
                    type="button"
                    key={number}
                    onClick={() => goTo(number)}
                    aria-current={number === currentPage ? 'page' : undefined}
                    className={cn(
                      'h-9 min-w-9 rounded-lg border px-3 text-sm font-medium transition',
                      number === currentPage
                        ? 'border-primary bg-primary text-primary-foreground'
                        : 'bg-card hover:border-primary/40 hover:text-primary',
                    )}
                  >
                    {number}
                  </button>
                ))}
                <button
                  type="button"
                  onClick={() => goTo(currentPage + 1)}
                  disabled={currentPage === pageCount}
                  className="inline-flex h-9 items-center gap-1 rounded-lg px-3 text-sm text-muted-foreground transition hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-40"
                >
                  {next}
                  <ChevronRight className="h-4 w-4" aria-hidden="true" />
                </button>
              </nav>
            ) : null}
          </div>

          <aside className="space-y-10 lg:border-l lg:pl-10">
            <form role="search" onSubmit={submitSearch}>
              <label htmlFor={`${id}-busca`} className="text-lg font-bold">
                {searchTitle}
              </label>
              <div className="mt-3 flex gap-2">
                <Input
                  id={`${id}-busca`}
                  type="search"
                  value={draft}
                  onChange={(event) => {
                    setDraft(event.target.value)
                    if (!event.target.value) setQuery('')
                  }}
                  placeholder={searchPlaceholder}
                />
                <button
                  type="submit"
                  aria-label={searchButton}
                  className="flex h-10 w-10 shrink-0 items-center justify-center rounded-md bg-primary text-primary-foreground transition hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <Search className="h-4 w-4" aria-hidden="true" />
                </button>
              </div>
            </form>

            {recent.length ? (
              <div>
                <h2 className="text-lg font-bold">{recentTitle}</h2>
                <ul className="mt-4 space-y-5">
                  {recent.map((post) => (
                    <li key={post.slug}>
                      <Link
                        href={post.href}
                        className="group flex gap-4 rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        <span className="relative h-20 w-20 shrink-0 overflow-hidden rounded-xl bg-muted">
                          <Image
                            src={post.image.src}
                            alt=""
                            fill
                            className="object-cover transition duration-500 group-hover:scale-110"
                            sizes="80px"
                          />
                        </span>
                        <span className="min-w-0">
                          <PostDate post={post} className="text-muted-foreground" />
                          <span className="mt-1 line-clamp-3 text-sm font-semibold leading-snug group-hover:text-primary">
                            {post.title}
                          </span>
                          <span className="mt-2 block">
                            <ReadMore label={readMore} />
                          </span>
                        </span>
                      </Link>
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}

            {categories?.length || derivedCategories.length ? (
              <nav aria-labelledby={`${id}-categorias`}>
                <h2 id={`${id}-categorias`} className="text-lg font-bold">
                  {categoriesTitle}
                </h2>
                <ul className="mt-4 space-y-2 text-sm">
                  {categories?.length ? (
                    categories.map((item) => (
                      <li key={item.href}>
                        <Link
                          href={item.href}
                          className="text-muted-foreground underline-offset-4 transition hover:text-primary hover:underline"
                        >
                          {item.label}
                        </Link>
                      </li>
                    ))
                  ) : (
                    <>
                      {[null, ...derivedCategories].map((item) => (
                        <li key={item ?? 'all'}>
                          <button
                            type="button"
                            aria-pressed={category === item}
                            onClick={() => selectCategory(item)}
                            className={cn(
                              'text-left underline-offset-4 transition hover:text-primary hover:underline',
                              category === item
                                ? 'font-semibold text-primary underline'
                                : 'text-muted-foreground',
                            )}
                          >
                            {item ?? allLabel}
                          </button>
                        </li>
                      ))}
                    </>
                  )}
                </ul>
              </nav>
            ) : null}
          </aside>
        </div>
      </section>
    </>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { ArrowRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type BlogGridProps = {
  title?: string
  posts: Array<{
    slug: string
    title: string
    excerpt?: string
    image: { src: string; alt: string }
    date: string
    category?: string
    href?: string
  }>
  className?: string
}

export function BlogGrid({ title, posts, className }: BlogGridProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'blog-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="blog-title" className="mb-10 text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        <div className="grid gap-7 md:grid-cols-2 lg:grid-cols-3">
          {posts.map((post) => (
            <article
              key={post.slug}
              className="group overflow-hidden rounded-2xl border bg-card shadow-sm"
            >
              <Link
                href={post.href ?? `/blog/${post.slug}`}
                className="block focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <div className="relative aspect-video overflow-hidden bg-muted">
                  <Image
                    src={post.image.src}
                    alt={post.image.alt}
                    fill
                    className="object-cover transition duration-500 group-hover:scale-105"
                    sizes="(min-width: 1024px) 33vw, 50vw"
                  />
                </div>
                <div className="p-6">
                  <div className="flex gap-2 text-xs font-medium text-muted-foreground">
                    {post.category ? <span>{post.category}</span> : null}
                    <time dateTime={post.date}>{post.date}</time>
                  </div>
                  <h3 className="mt-3 text-xl font-semibold">{post.title}</h3>
                  {post.excerpt ? (
                    <p className="mt-2 line-clamp-3 text-sm leading-6 text-muted-foreground">
                      {post.excerpt}
                    </p>
                  ) : null}
                  <span className="mt-5 inline-flex items-center gap-2 text-sm font-semibold text-primary">
                    Ler artigo <ArrowRight className="h-4 w-4" aria-hidden="true" />
                  </span>
                </div>
              </Link>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

'use client'

import { useId, useState, type FormEvent, type HTMLAttributes } from 'react'
import { ArrowRight, CheckCircle2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'

export interface NewsletterFormProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onSubmit'> {
  title?: string
  description?: string
  placeholder?: string
  submitLabel?: string
  successMessage?: string
  errorMessage?: string
  variant?: 'inline' | 'card'
  consentLabel?: string
  onSubmit: (email: string) => Promise<void> | void
}

export function NewsletterForm({
  title = 'Receba nossas novidades',
  description,
  placeholder = 'voce@empresa.com',
  submitLabel = 'Inscrever-se',
  successMessage = 'Inscrição realizada com sucesso.',
  errorMessage = 'Não foi possível concluir a inscrição.',
  variant = 'card',
  consentLabel,
  onSubmit,
  className,
  ...props
}: NewsletterFormProps) {
  const id = useId()
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle')

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = event.currentTarget
    const email = String(new FormData(form).get('email') ?? '')
    setStatus('loading')
    try {
      await onSubmit(email)
      setStatus('success')
      form.reset()
    } catch {
      setStatus('error')
    }
  }

  return (
    <div
      className={cn(
        variant === 'card' && 'rounded-2xl border bg-card p-6 shadow-sm md:p-8',
        className,
      )}
      {...props}
    >
      {title ? <h2 className="text-2xl font-bold tracking-tight">{title}</h2> : null}
      {description ? <p className="mt-2 text-muted-foreground">{description}</p> : null}
      <form className="mt-5" onSubmit={handleSubmit}>
        <label htmlFor={id} className="sr-only">
          E-mail
        </label>
        <div
          className={cn('flex gap-2', variant === 'inline' ? 'flex-col sm:flex-row' : 'flex-col')}
        >
          <Input
            id={id}
            name="email"
            type="email"
            autoComplete="email"
            required
            placeholder={placeholder}
            aria-describedby={`${id}-status`}
          />
          <Button type="submit" disabled={status === 'loading'} className="shrink-0">
            {status === 'loading' ? 'Enviando…' : submitLabel}
            {status !== 'loading' ? (
              <ArrowRight className="ml-2 h-4 w-4" aria-hidden="true" />
            ) : null}
          </Button>
        </div>
        {consentLabel ? (
          <label className="mt-3 flex items-start gap-2 text-xs text-muted-foreground">
            <input
              type="checkbox"
              required
              className="mt-0.5 h-4 w-4 rounded border-input accent-primary"
            />
            <span>{consentLabel}</span>
          </label>
        ) : null}
        <div id={`${id}-status`} aria-live="polite" className="mt-3 min-h-5 text-sm">
          {status === 'success' ? (
            <p className="flex items-center gap-2 text-emerald-600">
              <CheckCircle2 className="h-4 w-4" />
              {successMessage}
            </p>
          ) : null}
          {status === 'error' ? <p className="text-destructive">{errorMessage}</p> : null}
        </div>
      </form>
    </div>
  )
}

import Link from 'next/link'
import { ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'

export type PageHeaderProps = {
  title: string
  description?: string
  eyebrow?: string
  breadcrumbs?: Array<{ label: string; href?: string }>
  align?: 'left' | 'center'
  size?: 'default' | 'compact'
  variant?: 'muted' | 'primary'
  className?: string
}

export function PageHeader({
  title,
  description,
  eyebrow,
  breadcrumbs,
  align = 'left',
  size = 'default',
  variant = 'muted',
  className,
}: PageHeaderProps) {
  const compact = size === 'compact'
  const primary = variant === 'primary'

  return (
    <header
      className={cn(
        primary
          ? 'bg-primary bg-gradient-to-br from-primary to-primary/80 text-primary-foreground'
          : 'border-b bg-muted/30',
        className,
      )}
    >
      <div
        className={cn(
          'container',
          compact ? 'py-8 md:py-10' : 'py-14 md:py-20',
          align === 'center' && 'text-center',
        )}
      >
        {breadcrumbs?.length ? (
          <nav
            aria-label="Navegação estrutural"
            className={cn(compact ? 'mb-3' : 'mb-6', align === 'center' && 'flex justify-center')}
          >
            <ol
              className={cn(
                'flex flex-wrap items-center gap-1',
                compact ? 'text-xs' : 'text-sm',
                primary ? 'text-primary-foreground/70' : 'text-muted-foreground',
              )}
            >
              {breadcrumbs.map((item, index) => (
                <li key={`${item.label}-${index}`} className="flex items-center gap-1">
                  {index > 0 ? (
                    <ChevronRight className={compact ? 'h-3 w-3' : 'h-4 w-4'} aria-hidden="true" />
                  ) : null}
                  {item.href ? (
                    <Link
                      href={item.href}
                      className={cn(
                        'hover:underline',
                        primary ? 'hover:text-primary-foreground' : 'hover:text-foreground',
                      )}
                    >
                      {item.label}
                    </Link>
                  ) : (
                    <span
                      aria-current="page"
                      className={cn(primary && 'font-medium text-primary-foreground')}
                    >
                      {item.label}
                    </span>
                  )}
                </li>
              ))}
            </ol>
          </nav>
        ) : null}
        {eyebrow ? (
          <p
            className={cn(
              'font-semibold uppercase tracking-widest',
              compact ? 'mb-2 text-xs' : 'mb-3 text-sm',
              primary ? 'text-primary-foreground/80' : 'text-primary',
            )}
          >
            {eyebrow}
          </p>
        ) : null}
        <h1
          className={cn(
            'font-bold tracking-tight',
            compact ? 'text-2xl sm:text-3xl' : 'text-4xl sm:text-5xl',
          )}
        >
          {title}
        </h1>
        {description ? (
          <p
            className={cn(
              'max-w-2xl',
              compact ? 'mt-2 text-base' : 'mt-4 text-lg',
              primary ? 'text-primary-foreground/80' : 'text-muted-foreground',
              align === 'center' && 'mx-auto',
            )}
          >
            {description}
          </p>
        ) : null}
      </div>
    </header>
  )
}

import { cn } from '@/lib/utils'

/** Logo oficial Bloomin (PNG embutido para funcionar no catálogo e nos projetos instalados). */
const BLOOMIN_LOGO_SRC =
  'data:image/png;base64,'

export const BLOOMIN_URL = 'https://bloomin.com.br'

export type BloominLogoProps = {
  className?: string
  /** Altura visual do logo (largura acompanha a proporção). */
  height?: number
}

export function BloominLogo({ className, height = 18 }: BloominLogoProps) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- data URI portátil no registry
    <img
      src={BLOOMIN_LOGO_SRC}
      alt="Bloomin"
      width={Math.round(height * (421 / 108))}
      height={height}
      className={cn('h-[1.125rem] w-auto', className)}
      style={{ height, width: 'auto' }}
    />
  )
}

export type BloominCreditProps = {
  label?: string
  href?: string
  className?: string
  /** Fundo escuro atrás do logo (o PNG oficial tem fundo preto). */
  logoClassName?: string
}

/** Crédito padrão “Desenvolvido por” com o logo da Bloomin. */
export function BloominCredit({
  label = 'Desenvolvido por',
  href = BLOOMIN_URL,
  className,
  logoClassName,
}: BloominCreditProps) {
  return (
    <span className={cn('inline-flex items-center gap-2 text-sm', className)}>
